//! Recovered 0.97.2 enemy-death pickups and permanent boss equipment rolls.
//!
//! SHA-256 a64895f593c02d41aa682570f4ebabb67838146ba9b32e4ff4184b8958a92589.
//! Owners: ordinary definition path 0x1454c487e..0x1454c4d46; boss equipment
//! 0x1454c47cb..0x1454c4abd and 0x1454589f0, 0x14552cb40, 0x1455287e0.
//! Curated byte provenance and native differential fixtures are generated by
//! `scripts/recover-mob-loot-0972.py`. No reference executable is needed to build.
//!
//! These routines are source components. The owning engine must call them once
//! after a live enemy transitions to dead, route pickups through its shared
//! creator, and deliver queued gear through its recovered completion/persistence
//! path. They do not implement combat, pickup rendering, inventory delivery or
//! a gameplay loop in the menu application.

use crate::treasure_chests::{EnemyDefinition, NativeRng, Position};

#[path = "mob_loot_catalog.rs"]
mod catalog;
pub use catalog::BOSS_ZONES;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum PickupDrop {
    Experience { amount: u32, position: Position },
    Gold { amount: u32, position: Position },
    Cache { position: Position },
    /// Selected0.105.0 kinds3..5; see run_pickups and its owning report.
    Rune { rune: crate::run_pickups::Rune, position: Position },
    Magnet { position: Position },
}

/// Adapters for native shared creator 0x1454c8110 and the height-chain query
/// 0x1454606b0. Callers may route Cache to ChestField::create_chest; experience
/// and gold require their own creator arms rather than cache entities.
pub trait MobLootWorld {
    fn create_pickup(&mut self, pickup: PickupDrop);
    /// Bind the shared creator's RNG work (Gold uses1454d2850's yaw draw).
    /// Pure drop-recording ports can retain their existing callback.
    fn create_pickup_with_rng(&mut self, pickup: PickupDrop, _rng: &mut NativeRng) {
        self.create_pickup(pickup);
    }
    fn resolved_height(&mut self, xy: [f32; 2]) -> f32;
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct MobLootState {
    /// Native Game +0x910: decaying kill credit used by the ordinary enemy
    /// spawn-budget acceleration. The Game adapter must share this exact field
    /// with enemies::spawning; do not maintain independent loot/spawn copies.
    pub death_accumulator: f32,
}

/// Top 24 output bits scaled by exactly 2^-24, as inlined by the death owner.
/// Chest placement uses a different 23-bit conversion of the same RNG state.
pub fn unit24(rng: &mut NativeRng) -> f32 {
    (rng.next_u64() >> 40) as u32 as f32 * f32::from_bits(0x3380_0000)
}

/// Native 0x1454f9a40: widening multiply with its original rejection bound.
/// Consumes every rejected draw from the shared owning Game RNG.
pub fn range_u32(rng: &mut NativeRng, lower: u32, upper: u32) -> u32 {
    let width = upper.wrapping_sub(lower);
    assert!(lower < upper);
    let limit = width.wrapping_shl(width.leading_zeros()).wrapping_sub(1);
    loop {
        let product = (rng.next_u64() >> 32) * u64::from(width);
        if product as u32 <= limit {
            return lower.wrapping_add((product >> 32) as u32);
        }
    }
}

impl MobLootState {
    /// Ordinary-definition arm only: native entities with neither a primary
    /// boss definition nor guardian index. Unknown definitions do nothing.
    /// `density_percent` is the u16 run field +0x230, with no invented clamp.
    /// Native treats flag==1 specially for XP and flag!=0 for gold/cache.
    pub fn enemy_death(
        &mut self,
        definition: Option<&EnemyDefinition>,
        density_percent: u16,
        position: Position,
        rng: &mut NativeRng,
        world: &mut impl MobLootWorld,
    ) {
        let Some(definition) = definition else { return };
        let density = density_percent as f32 / 100.0;
        let scale = f32::from_bits(0x3fd3_3333) / density;
        let xp = if definition.chest_flag == 1 {
            definition.base_experience
        } else {
            self.death_accumulator += definition.death_accumulator;
            let value = definition.base_experience as f32 * scale;
            let base = value as u32;
            // The original consumes this draw even for an integral/zero XP.
            let random = unit24(rng);
            base.wrapping_add(u32::from(value - value.floor() > random))
        };
        if xp != 0 {
            world.create_pickup_with_rng(
                PickupDrop::Experience {
                    amount: xp,
                    position,
                },
                rng,
            );
        }
        let chance = if definition.chest_flag == 0 {
            scale * 0.1
        } else {
            1.0
        };
        // The guaranteed case still consumes a native chance draw.
        if chance > unit24(rng) {
            let amount = if definition.chest_flag == 0 {
                range_u32(rng, 0, 3) + 2
            } else {
                15
            };
            world.create_pickup_with_rng(
                PickupDrop::Gold {
                    amount,
                    position: Position::new(position.x + 0.8, position.y + 0.8, position.z),
                },
                rng,
            );
        }
        if definition.chest_flag != 0 {
            let xy = [position.x + 2.0, position.y - 1.0];
            let z = world.resolved_height(xy);
            world.create_pickup_with_rng(
                PickupDrop::Cache {
                    position: Position::new(xy[0], xy[1], z),
                },
                rng,
            );
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct BossDefinition {
    pub name: &'static str,
    /// Original boss definition +0x54. The final boss uses the weapon pool.
    pub final_flag: u8,
}

#[derive(Clone, Copy, Debug)]
pub struct BossZone {
    pub key: &'static str,
    pub tier: u8,
    pub base_drop_chance: f32,
    pub bosses: [BossDefinition; 5],
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EquipmentCandidate {
    pub item_id: u32,
    pub base_chance: f32,
}

/// 0x1454589f0 candidate mapping. The first eight armor slots are distributed
/// round-robin over nonfinal bosses in all zones of the same native tier.
/// Final bosses instead offer class weapon slots starting at index 8.
pub fn boss_candidates(class: u8, zone: usize, boss: usize) -> Vec<EquipmentCandidate> {
    let Some(zone_def) = BOSS_ZONES.get(zone) else {
        return Vec::new();
    };
    let Some(boss_def) = zone_def.bosses.get(boss) else {
        return Vec::new();
    };
    let base = 100_000 + u32::from(class) * 1000 + u32::from(zone_def.tier.min(5)) * 10;
    let indices: Vec<usize> = if boss_def.final_flag != 0 {
        let count = match class {
            4 | 7 => 2,
            1 | 2 | 3 | 5 | 8 | 9 | 11 => 1,
            _ => 0,
        };
        (8..8 + count).collect()
    } else {
        let pool: Vec<_> = BOSS_ZONES
            .iter()
            .enumerate()
            .filter(|(_, other)| other.tier == zone_def.tier)
            .flat_map(|(z, other)| {
                other
                    .bosses
                    .iter()
                    .enumerate()
                    .filter(|(_, candidate)| candidate.final_flag == 0)
                    .map(move |(b, _)| (z, b))
            })
            .collect();
        let Some(ordinal) = pool.iter().position(|&entry| entry == (zone, boss)) else {
            return Vec::new();
        };
        (0..8)
            .filter(|index| index % pool.len() == ordinal)
            .collect()
    };
    indices
        .into_iter()
        .map(|index| EquipmentCandidate {
            item_id: base + index as u32 * 100,
            base_chance: zone_def.base_drop_chance,
        })
        .collect()
}

/// 0x145451160. Four native u16 run-option percentages contribute in the
/// recovered SSE instruction order; the result has an upper cap of 2 only.
pub fn equipment_drop_multiplier(options: [u16; 4]) -> f32 {
    let values = options.map(|value| (value as f32 - 100.0) / 100.0);
    let a = values[0] * 0.05;
    let b = values[1] * 0.4;
    let c = values[2] * 0.6;
    let d = values[3] * 2.0;
    (d + ((b + a) + c) + 1.0).min(2.0)
}

#[derive(Clone, Copy, Debug)]
pub struct EquipmentRoll {
    /// Native Game +0x958: suppresses the whole permanent-gear roll arm.
    pub extra_pickup_mode: bool,
    /// Native Game +0x208, added to each candidate before multiplication.
    pub additive_chance: f32,
    pub run_options: [u16; 4],
}

/// Native Game +0x5a0/+0x5a8 queued item IDs. The native completion owner later
/// consumes this queue; these rolls do not directly equip or persist items.
pub fn roll_boss_equipment(
    class: u8,
    zone: usize,
    boss: usize,
    roll: EquipmentRoll,
    rng: &mut NativeRng,
) -> Vec<u32> {
    if roll.extra_pickup_mode {
        return Vec::new();
    }
    let multiplier = equipment_drop_multiplier(roll.run_options);
    boss_candidates(class, zone, boss)
        .into_iter()
        .filter(|candidate| {
            (candidate.base_chance + roll.additive_chance) * multiplier > unit24(rng)
        })
        .map(|candidate| candidate.item_id)
        .collect()
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct BossGearReward {
    pub marks: f32,
    pub items: Vec<u32>,
    pub missed_ids: Vec<u32>,
}

/// Current0.121.0 145c135f0: marks and recipient-private per-piece pity use
/// the same accepted boss definition and shared run RNG. Run Options no longer
/// determine this roll. `endless_bosses` is present only after the victory phase;
/// its caller increments the counter before invoking this owner.
pub fn roll_boss_rewards(
    class: u8,
    zone: usize,
    boss: usize,
    roll: EquipmentRoll,
    heroic_rank: u8,
    endless_bosses: Option<u32>,
    pity: &mut std::collections::BTreeMap<u32, u8>,
    rng: &mut NativeRng,
) -> BossGearReward {
    // The live run uses current zone order; the recovered legacy loot pools
    // still use their own order. Keep the new zone out of those pools.
    let Some(zone) = crate::guardians::catalog::ZONES.get(zone)
        .and_then(|current| BOSS_ZONES.iter().position(|row| row.key == current.key))
    else {
        return BossGearReward::default();
    };
    let Some(definition) = BOSS_ZONES.get(zone).and_then(|zone| zone.bosses.get(boss)) else {
        return BossGearReward::default();
    };
    if roll.extra_pickup_mode { return BossGearReward::default(); }
    let mut marks = (zone / 2 + 1) as f32;
    if let Some(count) = endless_bosses {
        marks *= count.max(1) as f32;
    } else if definition.final_flag != 0 {
        marks *= 3.;
    }
    marks *= crate::heroic::marks_multiplier(heroic_rank);
    let mut reward = BossGearReward { marks, ..BossGearReward::default() };
    let multiplier = crate::heroic::reward_multiplier(heroic_rank);
    for candidate in boss_candidates(class, zone, boss) {
        let bonus = f32::from(pity.get(&candidate.item_id).copied().unwrap_or(0)) * 0.1;
        let chance = ((candidate.base_chance + roll.additive_chance) + bonus) * multiplier;
        if chance > unit24(rng) {
            reward.items.push(candidate.item_id);
            pity.remove(&candidate.item_id);
        } else {
            reward.missed_ids.push(candidate.item_id);
            let misses = pity.entry(candidate.item_id).or_default();
            *misses = misses.saturating_add(1);
        }
    }
    reward
}

#[cfg(test)]
mod current_gear_tests {
    use super::*;
    use std::collections::BTreeMap;

    #[test]
    fn current_boss_marks_and_pity_are_independent_of_run_options() {
        let mut pity = BTreeMap::from([(101000, 255)]);
        let mut rng = NativeRng::from_words([1, 2, 3, 4]);
        let roll = EquipmentRoll { extra_pickup_mode: false, additive_chance: f32::NEG_INFINITY,
            run_options: [500, 500, 300, 150] };
        let reward = roll_boss_rewards(1, 0, 0, roll, 0, None, &mut pity, &mut rng);
        assert_eq!(reward.marks, 0.5);
        assert!(reward.items.is_empty());
        assert_eq!(reward.missed_ids, [101000]);
        assert_eq!(pity[&101000], 255);
        let reward = roll_boss_rewards(1, 0, 4, roll, 5, None, &mut pity, &mut rng);
        assert_eq!(reward.marks, 7.5);
        let reward = roll_boss_rewards(1, 0, 4, roll, 5, Some(3), &mut pity, &mut rng);
        assert_eq!(reward.marks, 7.5);
    }
}
